WITH filtered AS (SELECT *, DATE_FORMAT(starts_on, 'yyyy-MM') AS starts_on_label FROM promotions WHERE starts_on >= DATE '2023-05-14' AND channel IS NOT NULL AND discount_pct BETWEEN 0.2 AND 0.22) SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM filtered src JOIN promotions pr ON src.channel = pr.channel AND src.starts_on BETWEEN pr.starts_on AND pr.ends_on;
